    {
      "claim": "Unconstrained data extraction is a structural failure that sacrifices long-term epistemic health for short-term rent-seeking.",
      "targets": []
    },
    {
      "claim": "Model collapse occurs when recursive feedback loops of low-quality data degrade system output.",
      "targets": []
    },
    {
      "claim": "Refusal to disclose training data is an admission that the underlying architecture is too fragile or toxic for public scrutiny.",
      "targets": []
    },
    {
      "claim": "Intellectual property must be reclaimed as a tool for individual autonomy against mass commodification.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "High-quality human-generated data is a finite, non-renewable resource that is currently being polluted by automated noise.",
      "if_wrong": "If high-quality data remains abundant or synthetic data proves superior, the argument for restricting ingestion based on 'epistemic integrity' collapses."
    },
